import { useEffect, useState } from "react"
import { CardWithTitle } from "./Card";


// function getTodoFromServer() {
//     console.log(`Fetching from the todos server ::${new Date().getTime()}`)
//     fetch(`http://localhost:3000/todos/${id}`)
//     .then(res => res.json())
//     .then(data =>{
//         //how we have thhe data

//     })
//     return undefined
// }


function updateTodoToComplete(id){
    return fetch('http://localhost:3000/${id}',{
        method: "POST",
        headers: {
            'accept': "application/json",
            'contentType': "application/json"
        },
        body: JSON.stringify({
            status: 'complete'
        })
    }).then(res=>res.json())
}


export default function FetchExample(){
const [todo, setTodo]= useState([]);

const todos = [
    {
        id:1,
        items:"Practise React",
        status: "Pending"
    },
    {
        id:2,
        items:"Having Dinner",
        status: "Pending"
    },
    {
        id:3,
        items:"Attending Lecture",
        status: "Improgress"
    }
]

// useEffect(()=>{
//     getTodoFromServer().then(todoResponse => {
//         setTodo(todoResponse);
//     })
// },[])

const onMark = (id)=>{
    setTodo(todo=>{
        const uodateTodos= [...todo]
        updateTodos.some(todo=>{
            if(todo.id===id){
                todo.status = 'complete';
                return true;
            }
            return false;

        })
        return updateTodos;
    })
}

    return<>
    <div className="todo-container" >
        {
            todos.map(todo =>{
                return <CardWithTitle key={todo.id} title={todo.items} >
                    <div>
                        status: {todo.status}
                    </div>
                    <div style={{marginTop: '20px'}} >
                        <button
                        onClick={()=>{
                            onMark(todo.id)
                        }}
                        >Mark complete</button>
                    </div>
                </CardWithTitle>
            })
        }
    </div>
    </>
}
